  ('hi', 'crm', 'a836c556d0b263f0942a6668f3b4c794', $i18n$Suspended and removed accounts$i18n$, $i18n$निलंबित और हटाए गए खाते$i18n$, true),
  ('hi', 'crm', '8d0daf8cc73f4cde77447e6650f2a467', $i18n$Suspension record$i18n$, $i18n$निलंबन रिकॉर्ड$i18n$, true),
  ('hi', 'crm', '5abba8a77cee85dda9f12471f9ae7668', $i18n$Suspension takes a person out of public view at once. Only the Super Admin sees these accounts, decides frozen commission and active deals, and reinstates.$i18n$, $i18n$निलंबन किसी व्यक्ति को तुरंत सार्वजनिक दृश्य से हटा देता है। केवल सुपर एडमिन ये खाते देखते हैं, रोके गए कमीशन और सक्रिय सौदों का निर्णय लेते हैं, और बहाल करते हैं।$i18n$, true),
